package dapr4s.workflow

import dapr4s.*

import language.experimental.safe

/** Unique identifier of a workflow instance.
  *
  * Auto-generated by [[WorkflowCapability.start]] when not specified, or supplied explicitly via
  * [[WorkflowCapability.startWithId]]. Narrow the universal capability to one instance with `workflow(id)`, which
  * yields a [[WorkflowCapability.Instance]] for the per-instance operations (status, suspend, resume, terminate,
  * raiseEvent, …). May be empty when auto-generated (the sidecar assigns a UUID-based value).
  */
opaque type WorkflowInstanceId = String
object WorkflowInstanceId:
  def apply(s: String): WorkflowInstanceId = s
  extension (id: WorkflowInstanceId) def value: String = id
